type Row = Outputs["requests"]["list"]["data"][number];
type Detail = Outputs["requests"]["get"];
type Input<K extends keyof Inputs["requests"]> = Inputs["requests"][K];

const PAGE_SIZE = 200;
const KEY = ["requests"] as const;

function idOf(raw: string) {
  return raw;
}

function canCreate(user: SessionUser | null): boolean {
  return user !== null;
}

function canUpdate(user: SessionUser | null, row: Detail): boolean {
  return ((user !== null && row.requester_id === user.id && String(row.status) === "pending") && user !== null);
}

function canDelete(user: SessionUser | null, row: Detail): boolean {
  return user !== null;
}

function canApprove(user: SessionUser | null, row: Detail): boolean {
  return user !== null;
}

function canDecline(user: SessionUser | null, row: Detail): boolean {
  return user !== null;
}

function canReopen(user: SessionUser | null, row: Detail): boolean {
  return (user !== null && row.requester_id === user.id && user !== null);
}

/** Who may open this page */
function canOpen(user: SessionUser | null): boolean {
  return user !== null;
}

function AccessGate({ user }: { user: SessionUser | null }) {
  return (
    <div className="mx-auto max-w-md p-6">
      <Card>
        <CardHeader>
          <CardTitle>{user ? "No access" : "Sign in required"}</CardTitle>
          <CardDescription>{user ? "Your account cannot open this page." : "Sign in to open this page."}</CardDescription>
        </CardHeader>
        {user ? null : (
          <CardContent>
            <Link to="/login" className={buttonVariants()}>
              Sign in
            </Link>
          </CardContent>
        )}
      </Card>
    </div>
  );
}

/** Waits for the session, then renders the page or the gate */
function guarded<P extends object>(Component: (props: P) => ReactNode) {
  return function Guarded(props: P) {
    const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
    if (session.isPending) return <PaneSkeleton />;
    const user = sessionUser(session.data);
    if (!canOpen(user)) return <AccessGate user={user} />;
    return <Component {...props} />;
  };
}

const REQUESTS_FIELDS = ["team_id", "title", "amount"] as const;
type RequestsField = (typeof REQUESTS_FIELDS)[number];

type RequestsValues = {
  team_id: string;
  title: string;
  amount: string;
};

const EMPTY_REQUESTS: RequestsValues = {
  team_id: "",
  title: "",
  amount: ""
};

const REQUESTS_CREATE: readonly RequestsField[] = ["team_id", "title", "amount"];

function toRequestsCreateInput(v: RequestsValues): Input<"create"> {
  return {
    team_id: v.team_id,
    title: v.title,
    amount: Number(v.amount)
  };
}

const REQUESTS_UPDATE: readonly RequestsField[] = ["title", "amount"];

function toRequestsUpdateInput(v: RequestsValues): Input<"update">["data"] {
  return {
    title: v.title,
    amount: Number(v.amount)
  };
}

function requestsFromRow(row: Detail): RequestsValues {
  return {
    team_id: text(row.team_id),
    title: text(row.title),
    amount: text(row.amount)
  };
}

/** Picks a Team from the teams resource */
function TeamIdPicker({
  id,
  value,
  onChange,
  allowEmpty
}: {
  id: string;
  value: string;
  onChange: (value: string) => void;
  allowEmpty: boolean;
}) {
  const options = useQuery({ queryKey: ["teams", "list", { page_size: 200 }], queryFn: () => client.teams.list({ page_size: 200 }) });
  return (
    <select id={id} className={selectClass} value={value} onChange={e => onChange(e.target.value)}>
      {allowEmpty ? <option value="">—</option> : null}
      {(options.data?.data ?? []).map(item => (
        <option key={text(item.id)} value={text(item.id)}>
          {text(item.name)}
        </option>
      ))}
    </select>
  );
}

type RequestsSetter = <K extends keyof RequestsValues>(key: K, value: RequestsValues[K]) => void;

function renderRequestsField(field: RequestsField, values: RequestsValues, set: RequestsSetter) {
  switch (field) {
    case "team_id":
      return (
      <FormRow label="Team" htmlFor="team_id">
        <TeamIdPicker id="team_id" value={values.team_id} onChange={value => set("team_id", value)} allowEmpty={false} />
      </FormRow>
      );
    case "title":
      return (
      <FormRow label="Title" htmlFor="title">
        <Input id="title" type="text" maxLength={160} value={values.title} onChange={e => set("title", e.target.value)} required />
      </FormRow>
      );
    case "amount":
      return (
      <FormRow label="Amount" htmlFor="amount">
        <Input id="amount" type="number" step="1" value={values.amount} onChange={e => set("amount", e.target.value)} required />
      </FormRow>
      );
  }
}

function RequestsForm({
  fields,
  initial,
  submitLabel,
  pending,
  error,
  onSubmit,
  onCancel
}: {
  fields: readonly RequestsField[];
  initial: RequestsValues;
  submitLabel: string;
  pending: boolean;
  error: { message: string } | null;
  onSubmit: (values: RequestsValues) => void;
  onCancel?: () => void;
}) {
  const [values, setValues] = useState<RequestsValues>(initial);
  const [problem, setProblem] = useState<string | null>(null);
  const set: RequestsSetter = (key, value) => setValues(current => ({ ...current, [key]: value }));
  const submit = (event: FormEvent) => {
    event.preventDefault();
    setProblem(null);
    try {
      onSubmit(values);
    } catch (err) {
      setProblem(err instanceof Error ? err.message : String(err));
    }
  };
  return (
    <form onSubmit={submit} className="grid max-w-xl gap-4">
      {fields.map(field => (
        <Fragment key={field}>{renderRequestsField(field, values, set)}</Fragment>
      ))}
      <ErrorNote error={error ?? (problem ? { message: problem } : null)} />
      <div className="flex gap-2">
        <Button type="submit" disabled={pending}>
          {submitLabel}
        </Button>
        {onCancel ? (
          <Button type="button" variant="ghost" onClick={onCancel}>
            Cancel
          </Button>
        ) : null}
      </div>
    </form>
  );
}

function RequestsLayoutInner() {
  return <div className="h-full min-h-0 overflow-hidden"><Outlet /></div>;
}

const BOARD_INPUT = { page: 1, page_size: PAGE_SIZE } as Inputs["requests"]["list"];
const COLUMNS = ["pending", "approved", "declined", "expired"] as const;
type Column = (typeof COLUMNS)[number];

/** The transitions of Request: a card moves from one column to another only along one of these */
interface Move {
  name: string;
  from: readonly string[];
  to: Column;
  /** Whether the viewer's rule lets them run it on this card */
  allowed(user: SessionUser | null, row: Row): boolean;
  run(id: Row["id"]): Promise<unknown>;
}

const MOVES: Move[] = [
  {
    name: "approve",
    from: ["pending"],
    to: "approved",
    allowed: (user, row) => user !== null,
    run: id => client.requests.approve({ id })
  },
  {
    name: "decline",
    from: ["pending"],
    to: "declined",
    allowed: (user, row) => user !== null,
    run: id => client.requests.decline({ id })
  },
  {
    name: "reopen",
    from: ["declined"],
    to: "pending",
    allowed: (user, row) => (user !== null && row.requester_id === user.id && user !== null),
    run: id => client.requests.reopen({ id })
  }
];

/** The transition that takes a card to a column from where it is, if the viewer may run one */
function moveTo(user: SessionUser | null, row: Row, column: Column): Move | undefined {
  return MOVES.find(move => move.to === column && move.from.includes(String(row.status)) && move.allowed(user, row));
}

function RequestsIndexInner() {
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  const boardInput = { ...BOARD_INPUT } as Inputs["requests"]["list"];
  const boardKey = [...KEY, "list", boardInput] as const;
  const list = useQuery({ queryKey: boardKey, queryFn: () => client.requests.list(boardInput) });
  const [openAction, setOpenAction] = useState<string | null>(null);
  void openAction;
  void setOpenAction;
  // The card in the air, the column that last refused it, and what the board says about a drop it did not take
  const [dragging, setDragging] = useState<Row | null>(null);
  const refusedBy = useRef<Column | null>(null);
  const [refusal, setRefusal] = useState<string | null>(null);
  const navigate = useNavigate();
  const queryClient = useQueryClient();

  const move = useMutation({
    mutationFn: ({ id, step }: { id: Row["id"]; step: Move }) => step.run(id),
    onMutate: async ({ id, step }) => {
      await queryClient.cancelQueries({ queryKey: boardKey });
      const previous = queryClient.getQueryData<Outputs["requests"]["list"]>(boardKey);
      if (previous) {
        queryClient.setQueryData<Outputs["requests"]["list"]>(boardKey, {
          ...previous,
          data: previous.data.map(row => (row.id === id ? { ...row, status: step.to } : row))
        });
      }
      return { previous };
    },
    onError: (_error, _input, context) => {
      if (context?.previous) queryClient.setQueryData(boardKey, context.previous);
    },
    onSettled: () => queryClient.invalidateQueries({ queryKey: KEY })
  });
  const rows = list.data?.data ?? [];
  return (
    <div
      className="flex h-full min-h-0 flex-col"
      onDragOverCapture={() => {
        refusedBy.current = null;
      }}
    >
      <PaneHeader title="Requests" count={list.data?.page.total}>
          {canCreate(user) ? (
            <Link to="/requests/new" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="New request">
              <Plus />
            </Link>
          ) : null}
      </PaneHeader>


      <ErrorNote error={move.error ?? list.error} className="m-4" />
      {refusal ? (
        <p role="status" data-board-refusal className="mx-4 mt-4 rounded-md border border-border bg-muted/40 px-3 py-2 text-sm text-muted-foreground">
          {refusal}
        </p>
      ) : null}
      {list.isPending ? (
        <ListSkeleton />
      ) : (
        <div className="flex min-h-0 flex-1 gap-4 overflow-x-auto p-4">
          {COLUMNS.map(column => {
            const offered = dragging && dragging.status !== column ? Boolean(moveTo(user, dragging, column)) : null;
            return (
              <section
                key={column}
                data-column={column}
                data-offered={offered === null ? undefined : offered}
                className={cn(
                  "flex w-72 shrink-0 flex-col rounded-lg border border-border bg-muted/30",
                  offered === true && "ring-2 ring-ring",
                  offered === false && "opacity-50"
                )}
                onDragOver={event => {
                  if (!dragging || dragging.status === column) return;
                  // Only a column a transition reaches takes the drop; over any other the browser shows no-drop
                  if (moveTo(user, dragging, column)) event.preventDefault();
                  else refusedBy.current = column;
                }}
                onDrop={event => {
                  event.preventDefault();
                  const step = dragging ? moveTo(user, dragging, column) : undefined;
                  if (dragging && step) move.mutate({ id: dragging.id, step });
                  setDragging(null);
                }}
              >
                <header className="flex items-center justify-between px-3 py-2 text-sm font-medium">
                  <span>{column}</span>
                  <span className="text-xs text-muted-foreground">{rows.filter(r => r.status === column).length}</span>
                </header>
                <div className="flex min-h-0 flex-1 flex-col gap-2 overflow-y-auto p-2">
                  {rows
                    .filter(r => r.status === column)
                    .map((row: Row) => (
                      <div
                        key={text(row.id)}
                        data-card={text(row.id)}
                        draggable
                        onDragStart={event => {
                          event.dataTransfer.setData("text/plain", text(row.id));
                          event.dataTransfer.effectAllowed = "move";
                          refusedBy.current = null;
                          setRefusal(null);
                          setDragging(row);
                        }}
                        onDragEnd={() => {
                          // Let go over a column no transition reaches: the card never left, and the board says why
                          if (refusedBy.current)
                            setRefusal(`No transition takes a card from ${row.status} to ${refusedBy.current}.`);
                          refusedBy.current = null;
                          setDragging(null);
                        }}
                        onClick={() => navigate({ to: "/requests/$id", params: { id: text(row.id) } })}
                        className="cursor-grab rounded-md border border-border bg-card p-3 text-sm shadow-xs hover:bg-accent/40 active:cursor-grabbing"
                      >
                        <div className="font-medium">{text(row.title) || text(row.id)}</div>
                        <div className="mt-1 text-xs text-muted-foreground">{[text(row.amount)].filter(Boolean).join(" · ")}</div>
                      </div>
                    ))}
                </div>
              </section>
            );
          })}
        </div>
      )}
    </div>
  );
}

function RequestsNewInner() {
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const createRow = useMutation({
    mutationFn: (input: Input<"create">) => client.requests.create(input),
    onSuccess: async row => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await navigate({ to: "/requests/$id", params: { id: text(row.id) } });
    }
  });
  return (
    <Pane title="New request" actions={<Link to="/requests" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="Back">
            <ArrowLeft />
          </Link>}>
      <RequestsForm
        fields={REQUESTS_CREATE}
        initial={EMPTY_REQUESTS}
        submitLabel="Create"
        pending={createRow.isPending}
        error={createRow.error}
        onSubmit={values => createRow.mutate(toRequestsCreateInput(values))}
      />
    </Pane>
  );
}

function RequestsDetailInner() {
  const { id: rawId } = useParams({ from: "/requests/$id" });
  const id = idOf(rawId);
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const [editing, setEditing] = useState(false);
  const [openAction, setOpenAction] = useState<string | null>(null);
  useEffect(() => {
    setEditing(false);
    setOpenAction(null);
  }, [id]);
  const query = useQuery({ queryKey: [...KEY, "get", id], queryFn: () => client.requests.get({ id }) });
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const updateRow = useMutation({
    mutationFn: (input: Inputs["requests"]["update"]) => client.requests.update(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      setEditing(false);
    }
  });
  const removeRow = useMutation({
    mutationFn: (input: Inputs["requests"]["delete"]) => client.requests.delete(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await navigate({ to: "/requests" });
    }
  });
  const approveAction = useMutation({
    mutationFn: (input: Inputs["requests"]["approve"]) => client.requests.approve(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  const declineAction = useMutation({
    mutationFn: (input: Inputs["requests"]["decline"]) => client.requests.decline(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  const reopenAction = useMutation({
    mutationFn: (input: Inputs["requests"]["reopen"]) => client.requests.reopen(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  if (query.isPending) return <PaneSkeleton />;
  if (query.error) return <ErrorNote error={query.error} className="m-6" />;
  const row: Detail = query.data;
  return (
    <Pane
      title={text(row.title) || "Request " + text(row.id)}
      actions={
        <>
          <Link to="/requests" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="Back">
            <ArrowLeft />
          </Link>
          {canApprove(user, row) && ["pending"].includes(String(row.status)) ? (
            <Button variant="outline" size="sm" disabled={approveAction.isPending} onClick={() => approveAction.mutate({ id })}>
              Approve
            </Button>
          ) : null}
          {canDecline(user, row) && ["pending"].includes(String(row.status)) ? (
            <Button variant="outline" size="sm" disabled={declineAction.isPending} onClick={() => declineAction.mutate({ id })}>
              Decline
            </Button>
          ) : null}
          {canReopen(user, row) && ["declined"].includes(String(row.status)) ? (
            <Button variant="outline" size="sm" disabled={reopenAction.isPending} onClick={() => reopenAction.mutate({ id })}>
              Reopen
            </Button>
          ) : null}
          {canUpdate(user, row) ? (
            <Button variant="outline" size="sm" onClick={() => setEditing(current => !current)}>
              {editing ? "Cancel" : "Edit"}
            </Button>
          ) : null}
          {canDelete(user, row) ? (
            <Button
              variant="destructive"
              size="sm"
              disabled={removeRow.isPending}
              onClick={() => {
                if (window.confirm("Delete this request?")) removeRow.mutate({ id });
              }}
            >
              Delete
            </Button>
          ) : null}
        </>
      }
    >

      <ErrorNote error={approveAction.error} className="mb-4" />
      <ErrorNote error={declineAction.error} className="mb-4" />
      <ErrorNote error={reopenAction.error} className="mb-4" />
      {editing ? (
        <RequestsForm
          fields={REQUESTS_UPDATE}
          initial={requestsFromRow(row)}
          submitLabel="Save"
          pending={updateRow.isPending}
          error={updateRow.error}
          onCancel={() => setEditing(false)}
          onSubmit={values => updateRow.mutate({ id, data: toRequestsUpdateInput(values) })}
        />
      ) : (
        <dl className="grid gap-3">
        <FieldRow label="Id">{text(row.id) || "—"}</FieldRow>
        <FieldRow label="Team">{text(row.team_id) || "—"}</FieldRow>
        <FieldRow label="Requester">{text(row.requester_id) || "—"}</FieldRow>
        <FieldRow label="Title">{text(row.title) || "—"}</FieldRow>
        <FieldRow label="Amount">{text(row.amount) || "—"}</FieldRow>
        <FieldRow label="Status">{row.status == null ? "—" : <Badge variant="secondary">{text(row.status)}</Badge>}</FieldRow>
        <FieldRow label="Decided At">{formatDateTime(row.decided_at) || "—"}</FieldRow>
        <FieldRow label="Created At">{formatDateTime(row.created_at) || "—"}</FieldRow>
        </dl>
      )}
    </Pane>
  );
}

export const RequestsLayout = guarded(RequestsLayoutInner);
export const RequestsIndex = guarded(RequestsIndexInner);
export const RequestsNew = guarded(RequestsNewInner);
export const RequestsDetail = guarded(RequestsDetailInner);
